int git_pkt_parse(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (!line || !head || !out) {
        return GIT_ERROR;
    }

    if (bufflen < 4) {
        return GIT_EBUFS;
    }

    if (memcmp(line, "0000", 4) == 0) {
        *head = NULL;
        *out = line + 4;
        return 0;
    }

    if (memcmp(line, "00", 2) == 0) {
        size_t pkt_len = 0;
        sscanf(line + 2, "%zx", &pkt_len);

        if (bufflen < pkt_len) {
            return GIT_EBUFS;
        }

        if (pkt_len == 0) {
            *head = NULL;
            *out = line + 4;
            return 0;
        }

        char *pkt_data = (char *)malloc(pkt_len);
        if (!pkt_data) {
            return GIT_ERROR;
        }

        memcpy(pkt_data, line + 4, pkt_len - 1);
        pkt_data[pkt_len - 1] = '\0';

        *head = (git_pkt *)pkt_data;
        *out = line + 4 + pkt_len;
        return 0;
    }

    if (memcmp(line, "data", 4) == 0) {
        return handle_data_packet(head, line, out, bufflen);
    }

    if (memcmp(line, "sideband", 8) == 0) {
        return handle_sideband_packet(head, line, out, bufflen);
    }

    if (memcmp(line, "ACK", 3) == 0) {
        return handle_ack_packet(head, line, out, bufflen);
    }

    if (memcmp(line, "flush", 5) == 0) {
        *head = NULL;
        *out = line + 5;
        return 0;
    }

    return GIT_ERROR;
}

int git_pkt_parse_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (!line || bufflen < 4) {
        return GIT_EBUFS;
    }

    size_t len;
    if (sscanf(line, "%4" SCNuMAX, &len) != 1) {
        return GIT_ERROR;
    }

    const char *packet_end = line + len;
    if ((size_t)(packet_end - line) > bufflen) {
        return GIT_EBUFS;
    }

    if (strncmp(line, "data", 4) == 0) {
        // Handle data packet
        // (Assuming git_pkt_data is a function to process data packets)
        if (git_pkt_data(head, line + 4, &packet_end) < 0) {
            return GIT_ERROR;
        }
    } else if (strncmp(line, "side", 4) == 0) {
        // Handle sideband packet
        // (Assuming git_pkt_sideband is a function to process sideband packets)
        if (git_pkt_sideband(head, line + 4, &packet_end) < 0) {
            return GIT_ERROR;
        }
    } else if (strncmp(line, "ack", 3) == 0) {
        // Handle acknowledgment packet
        // (Assuming git_pkt_ack is a function to process acknowledgment packets)
        if (git_pkt_ack(head, line + 3, &packet_end) < 0) {
            return GIT_ERROR;
        }
    } else if (strncmp(line, "flush", 5) == 0) {
        // Handle flush packet
        git_pkt_flush(head);
    } else {
        return GIT_ERROR;
    }

    *out = packet_end;
    return 0;
}

int git_pkt_parse_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4) {
        return GIT_EBUFS;
    }

    int len;
    if (strncmp(line, "data", 4) == 0) {
        len = 4;
    } else if (strncmp(line, "sideband", 8) == 0) {
        len = 8;
    } else if (strncmp(line, "ack", 3) == 0) {
        len = 3;
    } else if (strncmp(line, "flush", 5) == 0) {
        len = 5;
    } else {
        return GIT_ERROR;
    }

    *head = (git_pkt *)malloc(sizeof(git_pkt));
    if (!*head) {
        return GIT_ERROR;
    }

    (*head)->data = strdup(line + len);
    if (!(*head)->data) {
        free(*head);
        *head = NULL;
        return GIT_ERROR;
    }

    *out = line + len;

    return 0;
}

int git_pkt_parse(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    int result = 0;
    const char *pos = line;

    if (bufflen < 4) {
        return GIT_EBUFS;
    }

    if (strncmp(pos, "data", 4) == 0) {
        result = git_pkt_read_data(head, line + 4, out);
    } else if (strncmp(pos, "sideband", 8) == 0) {
        result = git_pkt_read_sideband(head, line + 8, out);
    } else if (strncmp(pos, "ack", 3) == 0) {
        result = git_pkt_read_ack(head, line + 3, out);
    } else if (strncmp(pos, "flush", 5) == 0) {
        git_pkt_flush(head);
        *out = line + 5;
    } else {
        result = GIT_ERROR;
    }

    return result;
}

int git_pkt_parse(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4)
        return GIT_EBUFS;

    size_t len = 0;
    if (sscanf(line, "%4" SCNuMAX, &len) != 1)
        return GIT_EBUFS;

    if (len > bufflen)
        return GIT_EBUFS;

    if (strncmp(line, "data", 4) == 0) {
        int error = git_pkt_data(head, line + 4, out, len - 4);
        if (error)
            return error;
    } else if (strncmp(line, "sbnd", 4) == 0) {
        int error = git_pkt_sideband(head, line + 4, out, len - 4);
        if (error)
            return error;
    } else if (strncmp(line, "ack ", 4) == 0) {
        int error = git_pkt_ack(head, line + 4, out, len - 4);
        if (error)
            return error;
    } else if (strncmp(line, "flush", 4) == 0) {
        int error = git_pkt_flush(head);
        if (error)
            return error;
    } else {
        return GIT_ERROR;
    }

    *out = line + len;
    return 0;
}
